def find_code_spans(self, start, text):
    last = len(text)
    max_ticks = 0
    while start < last and text[start] == '`':
        max_ticks += 1
        start += 1
    longest_span = 0
    end = 0
    i = start
    while i < last:
        span_length = 0
        while i < last and text[i] == '`':
            span_length += 1
            i += 1
        if not span_length:
            i += 1
            continue
        if max_ticks == span_length:
            return start, i - span_length
        if max_ticks < span_length and span_length > longest_span:
            longest_span = span_length
            end = i
    if longest_span:
        return start - (max_ticks - longest_span), end - longest_span
    return None

